--
-- Name: v_amil_cashin; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_amil_cashin AS
 SELECT t.actualdate,
    t.branchcode AS branch_code,
    a.account_code,
    a.account_name,
    t.description,
    (i.amount)::double precision AS amount,
    t.referenceno,
    t.transactionno,
    t.inputer,
    t.authstatus,
        CASE t.channelcode
            WHEN 'R'::text THEN 'Kas Cabang'::text
            WHEN 'P'::text THEN 'Kas Kecil'::text
            WHEN 'A'::text THEN 'Bank'::text
            ELSE 'Aktiva'::text
        END AS channel,
    i.transactionitemid
   FROM ((transaction.transaction t
     JOIN transaction.transactionitem i ON ((t.transactionid = i.transactionid)))
     JOIN transaction.account a ON (((a.account_code)::text = (i.refaccountno)::text)))
  WHERE (((t.transactioncode)::text = 'CI'::text) AND ((i.mutationtype)::text = 'C'::text));


--
-- Name: v_amil_cashout; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_amil_cashout AS
 SELECT t.actualdate,
    t.branchcode AS branch_code,
    a.account_code,
    a.account_name,
    t.description,
    (
        CASE
            WHEN ((i.mutationtype)::text = 'D'::text) THEN i.amount
            ELSE (- i.amount)
        END)::double precision AS amount,
    t.referenceno,
    t.transactionno,
    t.inputer,
    t.authstatus,
        CASE t.channelcode
            WHEN 'R'::text THEN 'Kas Cabang'::text
            WHEN 'P'::text THEN 'Kas Kecil'::text
            WHEN 'A'::text THEN 'Bank'::text
            ELSE 'Aktiva'::text
        END AS channel,
    qb.budgetcode,
    qb.budgetitemdescription,
    i.transactionitemid
   FROM (((transaction.transaction t
     JOIN transaction.transactionitem i ON ((t.transactionid = i.transactionid)))
     JOIN transaction.account a ON (((a.account_code)::text = (i.refaccountno)::text)))
     LEFT JOIN ( SELECT bdt.transactionitemid,
            bdg.budgetcode,
            bdip.budgetitemdescription
           FROM (((transaction.budget bdg
             JOIN transaction.budgettransaction bdt ON ((bdg.budgetid = bdt.budgetid)))
             JOIN transaction.budgetitem bdi ON ((bdg.itemid = bdi.itemid)))
             JOIN transaction.budgetitem bdip ON ((bdi.parentitemid = bdip.itemid)))) qb ON ((qb.transactionitemid = i.transactionitemid)))
  WHERE (EXISTS ( SELECT 1
           FROM transaction.accounthierarchy ah
          WHERE (((ah.fl_parentaccountcode)::text = '530000'::text) AND ((ah.fl_childaccountcode)::text = (a.account_code)::text))));


--
-- Name: v_ar_account; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_ar_account AS
 SELECT a.accountno,
    a.accountname,
    a.branchcode AS branch_code,
    b.accountreceivabletype AS ar_type,
    c.description AS debtor_description
   FROM ((transaction.financialaccount a
     JOIN transaction.accountreceivable b ON (((a.accountno)::text = (b.accountno)::text)))
     LEFT JOIN transaction.externaldebtor c ON ((b.debtorid = c.debtorid)));


--
-- Name: v_aruskas_item_account; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_aruskas_item_account AS
 SELECT t.groupcode AS group_code,
    lower((t.itemcode)::text) AS item_code,
    ac.account_code,
    ac.account_type
   FROM (((transaction.balancesumitem t
     JOIN transaction.balancesumitemmember m ON ((m.itemid = t.itemid)))
     JOIN transaction.accounthierarchy ah ON (((m.account_code)::text = (ah.fl_parentaccountcode)::text)))
     JOIN transaction.account ac ON (((ah.fl_childaccountcode)::text = (ac.account_code)::text)));


--
-- Name: v_budget_summary; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_budget_summary AS
 SELECT b.budgetid AS budget_id,
    b.budgetcode AS budget_code,
    bo.ownerid AS owner_id,
    bo.ownername AS owner_name,
    bo.ownercode AS owner_code,
    bp.periodid AS period_id,
    bp.periodvalue AS period_year,
    b.branchcode AS branch_code,
    bi.itemid AS item_id,
    bi.budgetitemcode AS item_code,
    bi.budgetitemname AS item_name,
    bi.level,
    bi.parentitemid AS parent_item_id,
    (COALESCE(b.amount, (0)::double precision))::numeric(20,4) AS amount,
    (COALESCE(b.realization, (0)::double precision))::numeric(20,4) AS realization,
    ((COALESCE(b.amount, (0)::double precision) - COALESCE(b.realization, (0)::double precision)))::numeric(20,4) AS salvage_value,
    b.isdetail,
    b.budgettype,
    b.itemcode,
    b.itemname,
    b.currencycode,
    b.revisionid
   FROM (((transaction.budget b
     JOIN transaction.budgetowner bo ON ((b.ownerid = bo.ownerid)))
     JOIN transaction.budgetperiod bp ON (((b.periodid = bp.periodid) AND (bp.parentperiodid IS NULL))))
     LEFT JOIN transaction.budgetitem bi ON ((b.itemid = bi.itemid)))
  WHERE (((b.budgettype)::text = 'Y'::text) AND ((b.isdetail)::text = 'F'::text));


--
-- Name: v_budget_transaction; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_budget_transaction AS
 SELECT bt.transactionitemid AS transaction_item_id,
    bt.budgetid AS budget_id,
    b.budgetcode AS budget_code,
    b.budgetid AS header_budget_id,
    bo.ownerid AS owner_id,
    bo.ownername AS owner_name,
    bo.ownercode AS owner_code,
    bp.periodid AS period_id,
    bp.periodvalue AS period_year,
    b.branchcode AS branch_code,
    ti.transactionitemid,
    ti.transactionid,
    t.transactioncode,
    t.transactionno AS no_transaksi,
    (t.transactiondate)::date AS transaction_date,
    (t.actualdate)::date AS actual_date,
        CASE
            WHEN ((bt.budgettranstype)::text = 'A'::text) THEN (ti.amount)::numeric(20,4)
            ELSE (0)::numeric(20,4)
        END AS realization_amount,
        CASE
            WHEN ((bt.budgettranstype)::text <> 'A'::text) THEN (ti.amount)::numeric(20,4)
            ELSE (0)::numeric(20,4)
        END AS return_amount,
    bt.budgettranstype AS transaction_type,
    ti.amount AS full_amount,
    (ti.amount)::numeric(20,4) AS amount_numeric,
    ti.accountcode,
    ti.description,
    t.inputer,
    t.referenceno AS reference_no,
    t.authstatus,
    t.isposted,
    ti.currencycode
   FROM (((((transaction.budgettransaction bt
     JOIN transaction.budget b ON ((bt.budgetid = b.budgetid)))
     JOIN transaction.budgetowner bo ON ((b.ownerid = bo.ownerid)))
     JOIN transaction.budgetperiod bp ON ((b.periodid = bp.periodid)))
     JOIN transaction.transactionitem ti ON ((bt.transactionitemid = ti.transactionitemid)))
     JOIN transaction.transaction t ON ((ti.transactionid = t.transactionid)))
  WHERE ((b.budgettype)::text = 'Y'::text);


--
-- Name: v_cash_mutation; Type: VIEW; Schema: dwh; Owner: -
