    ca.currencycode AS currency_code,
    i.branchcode AS branch_code,
    t.actualdate,
    i.mutationtype,
    i.amount,
    ca.cashaccounttype AS account_type
   FROM (((transaction.accounttransactionitem a
     JOIN transaction.transactionitem i ON ((a.transactionitemid = i.transactionitemid)))
     JOIN transaction.transaction t ON ((i.transactionid = t.transactionid)))
     JOIN transaction.cashaccountall ca ON (((ca.accountno)::text = (a.accountno)::text)));


--
-- Name: v_cashadvance_trx; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_cashadvance_trx AS
 SELECT c.actualdate,
    g.branchcode AS branch_code,
    g.accountno,
    g.accountname,
    c.transactionno,
    c.referenceno,
    c.description,
    c.inputer,
    c.authstatus,
    (b.amount)::double precision AS amount,
    b.ekuivalenamount AS ekuiv,
    b.currencycode,
    d.full_name AS currency_name,
    f.employeeidnumber,
    (EXISTS ( SELECT 1
           FROM transaction.cashadvancereturninfo cr
          WHERE (cr.sourcetransactionid = c.transactionid))) AS has_lpj,
    rtt.transactionno AS return_transactionno,
    a.transactionitemid
   FROM (((((((transaction.accounttransactionitem a
     JOIN transaction.transactionitem b ON ((a.transactionitemid = b.transactionitemid)))
     JOIN transaction.transaction c ON ((b.transactionid = c.transactionid)))
     LEFT JOIN transaction.currency d ON (((c.currencycode)::text = (d.currency_code)::text)))
     JOIN transaction.accountreceivable f ON (((a.accountno)::text = (f.accountno)::text)))
     JOIN transaction.financialaccount g ON (((f.accountno)::text = (g.accountno)::text)))
     LEFT JOIN transaction.transactionitem rt ON ((rt.transactionitemid = a.returntransactionitemid)))
     LEFT JOIN transaction.transaction rtt ON ((rtt.transactionid = rt.transactionid)))
  WHERE (((a.accounttitype)::text = 'C'::text) AND ((a.cattype)::text = 'D'::text));


--
-- Name: v_collection; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_collection AS
 SELECT t.actualdate,
    i.branchcode AS branch_code,
    b.branchname AS branch_name,
    f.accountname AS account_name,
    t.description,
    a.fundentity AS fund_entity,
    a.donorid,
    t.channelcode AS channel_code,
        CASE t.channelcode
            WHEN 'R'::text THEN 'Kas Cabang'::text
            WHEN 'P'::text THEN 'Kas Kecil'::text
            WHEN 'A'::text THEN 'Bank'::text
            ELSE 'Aktiva'::text
        END AS channel,
        CASE
            WHEN ((i.mutationtype)::text = 'C'::text) THEN i.ekuivalenamount
            ELSE (- i.ekuivalenamount)
        END AS amount,
    t.donorname,
    t.marketerid,
    t.referenceno,
    t.inputer,
    t.transactionno,
    t.authstatus,
    i.currencycode,
    t.channelaccountno AS bank_account_no,
    fc.accountname AS bank_account_name,
    i.transactionitemid
   FROM (((((transaction.accounttransactionitem a
     JOIN transaction.transactionitem i ON ((a.transactionitemid = i.transactionitemid)))
     JOIN transaction.transaction t ON ((i.transactionid = t.transactionid)))
     JOIN transaction.financialaccount f ON (((a.accountno)::text = (f.accountno)::text)))
     JOIN transaction.branch b ON (((b.branchcode)::text = (i.branchcode)::text)))
     LEFT JOIN transaction.financialaccount fc ON (((fc.accountno)::text = (t.channelaccountno)::text)))
  WHERE ((a.accounttitype)::text = 'D'::text);


--
-- Name: v_daily_balance; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_daily_balance AS
 SELECT d.accountinstance_id,
    ai.account_code,
    a.account_name,
    a.account_type,
    a.account_level,
    a.is_detail,
    ai.branch_code,
    ai.currency_code,
    COALESCE(ai.balance_sign, (1)::numeric) AS balance_sign,
    d.datevalue,
    COALESCE(d.balancecumulative, (0)::numeric) AS balancecumulative,
    COALESCE(d.debit, (0)::numeric) AS debit,
    COALESCE(d.credit, (0)::numeric) AS credit
   FROM ((transaction.dailybalance d
     JOIN transaction.accountinstance ai ON ((ai.accountinstance_id = d.accountinstance_id)))
     JOIN transaction.account a ON (((a.account_code)::text = (ai.account_code)::text)));


--
-- Name: v_distribution; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_distribution AS
 SELECT t.actualdate,
    i.branchcode AS branch_code,
    b.branchname AS branch_name,
    gpr.productname AS product_name,
    f.accountname AS account_name,
    t.description,
    a.ashnaf,
    a.distributioncategory AS distribution_category,
    a.fundentity AS fund_entity,
    t.channelcode AS channel_code,
        CASE t.channelcode
            WHEN 'R'::text THEN 'Kas Cabang'::text
            WHEN 'P'::text THEN 'Kas Kecil'::text
            WHEN 'A'::text THEN 'Bank'::text
            ELSE 'Aktiva'::text
        END AS channel,
        CASE
            WHEN ((i.mutationtype)::text = 'D'::text) THEN i.ekuivalenamount
            ELSE (- i.ekuivalenamount)
        END AS amount,
    t.donorname,
    t.referenceno,
    t.inputer,
    t.transactionno,
    t.authstatus,
    t.channelaccountno AS bank_account_no,
    fc.accountname AS bank_account_name,
    qb.budgetcode,
    qb.budgetitemdescription,
    i.transactionitemid
   FROM (((((((((transaction.accounttransactionitem a
     JOIN transaction.transactionitem i ON ((a.transactionitemid = i.transactionitemid)))
     JOIN transaction.transaction t ON ((i.transactionid = t.transactionid)))
     JOIN transaction.financialaccount f ON (((a.accountno)::text = (f.accountno)::text)))
     JOIN transaction.branch b ON (((b.branchcode)::text = (i.branchcode)::text)))
     LEFT JOIN transaction.productaccount p ON (((p.accountno)::text = (f.accountno)::text)))
     LEFT JOIN transaction.product pr ON ((p.productid = pr.productid)))
     LEFT JOIN transaction.product gpr ON ((pr.parentproductid = gpr.productid)))
     LEFT JOIN transaction.financialaccount fc ON (((fc.accountno)::text = (t.channelaccountno)::text)))
     LEFT JOIN ( SELECT bdt.transactionitemid,
            bdg.budgetcode,
            bdip.budgetitemdescription
           FROM (((transaction.budget bdg
             JOIN transaction.budgettransaction bdt ON ((bdg.budgetid = bdt.budgetid)))
             JOIN transaction.budgetitem bdi ON ((bdg.itemid = bdi.itemid)))
             JOIN transaction.budgetitem bdip ON ((bdi.parentitemid = bdip.itemid)))) qb ON ((qb.transactionitemid = i.transactionitemid)))
  WHERE ((a.accounttitype)::text = 'Z'::text);


--
-- Name: v_export_penghimpunan_hc_batch; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_export_penghimpunan_hc_batch AS
 SELECT hbi.batchid AS batch_id,
    hb.batchperioddesc AS batch_name,
    (hb.transactiondate)::date AS batch_date,
    COALESCE(d.donorno, (hbi.donorid)::character varying) AS donor_number,
    COALESCE(d.donorname, hbi.name) AS donor_name,
    ''::text AS product_code,
    ''::text AS product_name,
    ((((((COALESCE(hbi.amountzakat, (0)::numeric) + COALESCE(hbi.amountinfaq, (0)::numeric)) + COALESCE(hbi.amountanakasuh, (0)::numeric)) + COALESCE(hbi.amountanakyatim, (0)::numeric)) + COALESCE(hbi.amountqurban, (0)::numeric)) + COALESCE(hbi.amountwakaf, (0)::numeric)))::numeric(20,4) AS donation_amount,
    (COALESCE(hbi.smslog_time, hb.transactiondate))::date AS donation_date
   FROM ((transaction.humancapitalbatchitem hbi
     LEFT JOIN transaction.humancapitalbatch hb ON ((hbi.batchid = hb.batchid)))
     LEFT JOIN fund.donor d ON ((hbi.donorid = d.donorid)))
  WHERE (hbi.batchid IS NOT NULL);


--
-- Name: v_export_penghimpunan_website; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_export_penghimpunan_website AS
 SELECT d.donorno AS donor_number,
    d.donorname AS donor_name,
    COALESCE(id.gender, ''::character varying) AS gender,
        CASE
            WHEN ((COALESCE(id.gender, ''::character varying))::text = 'P'::text) THEN 'Female'::text
            ELSE 'Male'::text
        END AS gender_display,
    COALESCE(id.maritalstate, ''::character varying) AS marital_state,
        CASE
            WHEN ((id.maritalstate)::text = 'K'::text) THEN 'Menikah'::text
            WHEN ((id.maritalstate)::text = 'B'::text) THEN 'Belum Menikah'::text
            WHEN ((id.maritalstate)::text = 'J'::text) THEN 'Cerai'::text
            ELSE ''::text
        END AS marital_display,
    COALESCE(d.addressstreet, ''::character varying) AS address,
    COALESCE(d.phonenumber, ''::character varying) AS phone_number,
    COALESCE(id.email, ''::character varying) AS email,
    COALESCE(id.corporatename, ''::character varying) AS organization_name,
    COALESCE(id.isinternalemployee, ''::character varying) AS is_internal_employee,
        CASE
            WHEN ((id.isinternalemployee)::text = 'T'::text) THEN 'Ya'::text
            ELSE 'Tidak'::text
        END AS employee_display,
    sum((ti.amount)::numeric(20,4)) AS total_donation,
    min((t.actualdate)::date) AS first_donation_date,
    max((t.actualdate)::date) AS last_donation_date,
    COALESCE(sum(
        CASE
            WHEN ((p.productcode)::text = ANY ((ARRAY['0101'::character varying, '0103'::character varying])::text[])) THEN (ti.amount)::numeric(20,4)
            ELSE (0)::numeric
        END), (0)::numeric) AS nominal_zakat,
    count(
        CASE
            WHEN ((p.productcode)::text = ANY ((ARRAY['0101'::character varying, '0103'::character varying])::text[])) THEN 1
            ELSE NULL::integer
        END) AS nominal_zakat_count,
    COALESCE(sum(
        CASE
            WHEN ((p.productcode)::text = '0102'::text) THEN (ti.amount)::numeric(20,4)
            ELSE (0)::numeric
        END), (0)::numeric) AS nominal_fitrah,
    count(
        CASE
            WHEN ((p.productcode)::text = '0102'::text) THEN 1
            ELSE NULL::integer
        END) AS nominal_fitrah_count,
    COALESCE(sum(
        CASE
            WHEN ((p.productcode)::text = '02021'::text) THEN (ti.amount)::numeric(20,4)
            ELSE (0)::numeric
        END), (0)::numeric) AS nominal_infak_sedekah,
    count(
        CASE
            WHEN ((p.productcode)::text = '02021'::text) THEN 1
            ELSE NULL::integer
        END) AS nominal_infak_sedekah_count,
    COALESCE(sum(
        CASE
            WHEN ((p.productcode)::text = '02011'::text) THEN (ti.amount)::numeric(20,4)
            ELSE (0)::numeric
        END), (0)::numeric) AS nominal_anak_asuh,
    count(
        CASE
            WHEN ((p.productcode)::text = '02011'::text) THEN 1
            ELSE NULL::integer
        END) AS nominal_anak_asuh_count,
    COALESCE(sum(
        CASE
            WHEN ((p.productcode)::text = '02012'::text) THEN (ti.amount)::numeric(20,4)
            ELSE (0)::numeric
        END), (0)::numeric) AS nominal_anak_yatim,
    count(
        CASE
            WHEN ((p.productcode)::text = '02012'::text) THEN 1
            ELSE NULL::integer
        END) AS nominal_anak_yatim_count,
    COALESCE(sum(
        CASE
            WHEN ((p.productcode)::text = '02014'::text) THEN (ti.amount)::numeric(20,4)
            ELSE (0)::numeric
        END), (0)::numeric) AS nominal_dpu,
    count(
        CASE
            WHEN ((p.productcode)::text = '02014'::text) THEN 1
            ELSE NULL::integer
        END) AS nominal_dpu_count,
    COALESCE(sum(
        CASE
            WHEN ((p.productcode)::text = '0301'::text) THEN (ti.amount)::numeric(20,4)
            ELSE (0)::numeric
        END), (0)::numeric) AS nominal_wakaf,
    count(
        CASE
            WHEN ((p.productcode)::text = '0301'::text) THEN 1
            ELSE NULL::integer
        END) AS nominal_wakaf_count,
    COALESCE(sum(
        CASE
            WHEN ((p.productcode)::text = ANY ((ARRAY['02013'::character varying, '0401'::character varying])::text[])) THEN (ti.amount)::numeric(20,4)
            ELSE (0)::numeric
        END), (0)::numeric) AS nominal_qurban,
    count(
        CASE
            WHEN ((p.productcode)::text = ANY ((ARRAY['02013'::character varying, '0401'::character varying])::text[])) THEN 1
            ELSE NULL::integer
        END) AS nominal_qurban_count
   FROM (((((((transaction.transaction t
     JOIN transaction.transactionitem ti ON ((t.transactionid = ti.transactionid)))
     JOIN transaction.accounttransactionitem ati ON ((ti.transactionitemid = ati.transactionitemid)))
     JOIN transaction.productaccount pa ON (((ati.accountno)::text = (pa.accountno)::text)))
     JOIN transaction.product p ON ((pa.productid = p.productid)))
     JOIN fund.donor d ON ((t.donorid = d.donorid)))
     LEFT JOIN fund.individualdonor id ON ((d.donorid = id.donorid)))
     LEFT JOIN fund.workarea wa ON ((id.workareaid = wa.workareaid)))
  GROUP BY d.donorid, d.donorno, d.donorname, id.donorid, id.gender, id.maritalstate, id.email, id.corporatename, id.isinternalemployee, d.addressstreet, d.phonenumber;


--
-- Name: v_general_ledger; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_general_ledger AS
 SELECT ac.account_code,
    ac.account_type,
    ac.account_name,
    ji.branch_code,
    j.journal_no,
    j.journal_date,
    t.transactionno,
    ji.additionaldescription,
    ji.description,
    ji.subaccountcode,
    ji.subaccountname,
    ((ji.amount_debit * ji.nilai_kurs))::double precision AS debit_ekuiv,
    ((ji.amount_credit * ji.nilai_kurs))::double precision AS credit_ekuiv,
    ac.fl_cpa_accountcode AS lawan_code,
    acpa.account_name AS lawan_name
   FROM ((((transaction.journalitem ji
     JOIN transaction.journal j ON (((ji.fl_journal)::text = (j.journal_no)::text)))
     JOIN transaction.account ac ON (((ji.fl_account)::text = (ac.account_code)::text)))
     LEFT JOIN transaction.transaction t ON ((t.journalblockid = ji.id_journalblock)))
     LEFT JOIN transaction.account acpa ON (((acpa.account_code)::text = (ac.fl_cpa_accountcode)::text)))
  WHERE ((ac.is_detail)::text = 'T'::text);


--
-- Name: v_general_transaction; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_general_transaction AS
 SELECT t.branchcode AS branch_code,
    t.actualdate,
    t.transactionid,
    t.transactionno,
    t.transactiondate,
    t.description AS header_description,
    t.inputer,
    ti.refaccountno,
    ti.refaccountname,
    ti.mutationtype,
    ti.amount,
    ti.description AS item_description,
    qb.budgetcode AS budget_code,
    qb.budgetitemdescription AS budget_item_description
   FROM transaction.transaction t,
    (transaction.transactionitem ti
     LEFT JOIN ( SELECT bdt.transactionitemid,
            bdg.budgetcode,
            bdip.budgetitemdescription
           FROM transaction.budget bdg,
            transaction.budgettransaction bdt,
            transaction.budgetitem bdi,
            transaction.budgetitem bdip
          WHERE ((bdg.budgetid = bdt.budgetid) AND (bdg.itemid = bdi.itemid) AND (bdi.parentitemid = bdip.itemid))) qb ON ((qb.transactionitemid = ti.transactionitemid)))
  WHERE ((t.transactionid = ti.transactionid) AND ((t.transactioncode)::text = 'GT'::text));


--
-- Name: v_journal_daily; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_journal_daily AS
 SELECT j.branch_code,
    j.journal_date,
    j.journal_no,
    t.transactionno,
    ji.branch_code AS account_branch_code,
    ac.account_code,
    ac.account_type,
    ac.account_name,
    ji.subaccountcode,
    ji.subaccountname,
        CASE
            WHEN (ji.additionaldescription IS NOT NULL) THEN (((((ji.description)::text || ' ( '::text) || (ji.additionaldescription)::text) || ' )'::text))::character varying
            ELSE ji.description
        END AS description,
    (ji.amount_debit * ji.nilai_kurs) AS debit_ekuiv,
    (ji.amount_credit * ji.nilai_kurs) AS credit_ekuiv,
    t.inputer
   FROM transaction.account ac,
    transaction.journal j,
    (transaction.journalitem ji
     LEFT JOIN transaction.transaction t ON ((t.journalblockid = ji.id_journalblock)))
  WHERE (((ji.fl_account)::text = (ac.account_code)::text) AND ((ji.fl_journal)::text = (j.journal_no)::text));


--
-- Name: v_piutang_karyawan; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_piutang_karyawan AS
 SELECT transactionid,
    transactionno,
    transactioncode,
    (actualdate)::date AS actualdate,
    branchcode,
    inputer,
    (amount)::numeric(20,4) AS amount,
    currencycode,
    referenceno,
    description,
    receivedfrom AS debtor_name,
    authstatus,
    (transactiondate)::timestamp with time zone AS transaction_timestamp,
    paidto
   FROM transaction.transaction t
  WHERE ((transactioncode)::text = ANY ((ARRAY['EAR'::character varying, 'PEAR'::character varying])::text[]));


--
-- Name: v_piutang_non_karyawan; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_piutang_non_karyawan AS
 SELECT transactionid,
    transactionno,
    transactioncode,
    (actualdate)::date AS actualdate,
    branchcode,
    inputer,
    (amount)::numeric(20,4) AS amount,
    currencycode,
    referenceno,
    description,
    receivedfrom AS debtor_name,
    authstatus,
    (transactiondate)::timestamp with time zone AS transaction_timestamp,
    paidto
   FROM transaction.transaction t
  WHERE ((transactioncode)::text = ANY ((ARRAY['EAR'::character varying, 'PEAR'::character varying])::text[]));


--
-- Name: v_program_realization; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_program_realization AS
 SELECT r.realizationid,
    r.realizationdate,
    (r.realizationamount)::double precision AS amount,
    r.realizationinputuser AS input_user,
    r.realizationtype AS realization_type,
    r.realizationdescription AS description,
    r.branchcode AS branch_code,
    m.realmemonumber AS memo_number,
    e.employeename AS employee_name,
    q.reportamount AS report_amount,
    q.receivablereportuserinput AS report_user,
    q.receivablereportdate AS report_date
   FROM (((program.realizationmemo m
     JOIN program.realization r ON ((m.realmemoid = r.realmemoid)))
     JOIN program.vemployee e ON (((r.employeeid)::text = (e.employeeid)::text)))
     LEFT JOIN ( SELECT t.realizationid,
            t.receivablereportuserinput,
            t.receivablereportdate,
            (sum(d.realizationamount))::double precision AS reportamount
           FROM (program.statusreceivablereport t
             JOIN program.statusrecrepdetail d ON ((t.statusreceivableid = d.statusreceivableid)))
          WHERE ((d.reportdetailstatus)::text = ANY ((ARRAY['1'::character varying, '2'::character varying])::text[]))
          GROUP BY t.realizationid, t.receivablereportuserinput, t.receivablereportdate) q ON ((q.realizationid = r.realizationid)))
  WHERE ((r.statusreceivables)::text = 'Y'::text);


--
-- Name: v_proposal_masuk; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_proposal_masuk AS
 SELECT p.proposalid AS proposal_id,
    p.proposalno AS proposal_no,
    (p.proposaldate)::date AS proposal_date,
    (p.proposalreceiveddate)::date AS received_date,
    p.proposaldescription AS description,
    p.proposalnominal AS nominal,
    p.proposalreceivedby AS received_by,
    p.proposalreferenceby AS reference_by,
    p.proposalreferenceposition AS reference_position,
    p.proposalstatus AS status,
    p.branchcode AS branch_code,
    p.mustahiqid AS mustahiq_id,
    c.customername AS mustahiq_name,
    c.addressstreet AS address_street,
    c.addresskelurahan AS address_kelurahan,
    c.addresskecamatan AS address_kecamatan,
    p.productgroupid AS product_group_id,
    pg.productgroupcode AS product_group_code,
    pg.productgroupname AS product_group_name,
    q.realizationdate AS realization_date,
    q.realizationamount AS realization_amount,
    q.memoamount AS memo_amount,
    q.realmemonumber AS memo_number,
    q.fundsourceno AS fund_source_no,
    q.fundsourcename AS fund_source_name
   FROM ((((program.proposal p
     JOIN program.productgroup pg ON ((pg.productgroupid = p.productgroupid)))
     JOIN program.mustahiq m ON ((m.mustahiqid = p.mustahiqid)))
     JOIN program.customer c ON ((c.customerid = m.customerid)))
     LEFT JOIN ( SELECT rd.mustahiqproductid,
            mp.proposalid,
            r.realizationdate,
            rd.realizationamount,
            (rd.memoamount)::double precision AS memoamount,
            rm.realmemonumber,
            mp.accountno AS fundsourceno,
            f.accountname AS fundsourcename,
            rank() OVER (PARTITION BY rd.mustahiqproductid ORDER BY rd.realizationamount DESC) AS data_rank
           FROM ((((program.realizationdetail rd
             JOIN program.realization r ON ((r.realizationid = rd.realizationid)))
             JOIN program.realizationmemo rm ON ((rm.realmemoid = r.realmemoid)))
             JOIN program.mustahiqproduct mp ON ((mp.mustahiqproductid = rd.mustahiqproductid)))
             JOIN transaction.financialaccount f ON (((f.accountno)::text = (mp.accountno)::text)))) q ON (((q.data_rank = 1) AND (q.proposalid = p.proposalid))));


--
-- Name: v_realization_memo; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_realization_memo AS
 SELECT m.realmemoid,
    m.realmemonumber AS memo_number,
    m.realmemodate AS memo_date,
    m.realmemosubject AS memo_subject,
    m.realmemoamount AS memo_amount,
    m.branchcode AS branch_code,
    (COALESCE(rz.total_realisasi, (0)::numeric))::double precision AS total_realisasi,
    COALESCE(rz.cnt, (0)::bigint) AS realisasi_count,
    (COALESCE(rt.total_return, (0)::numeric))::double precision AS total_return
   FROM ((program.realizationmemo m
     LEFT JOIN ( SELECT realization.realmemoid,
            sum(realization.realizationamount) AS total_realisasi,
            count(*) AS cnt
           FROM program.realization
          GROUP BY realization.realmemoid) rz ON ((rz.realmemoid = m.realmemoid)))
     LEFT JOIN ( SELECT r.realmemoid,
            sum(rr.returnamount) AS total_return
           FROM (program.realization r
             JOIN program.realizationreturn rr ON ((rr.realizationid = r.realizationid)))
          GROUP BY r.realmemoid) rt ON ((rt.realmemoid = m.realmemoid)));


--
-- Name: v_realization_return; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_realization_return AS
 SELECT rr.returnid AS return_id,
    (rr.returndate)::date AS return_date,
    rr.returndescription AS return_description,
    rr.returnamount AS return_amount,
    rr.costamount AS cost_amount,
    rr.realizationid AS realization_id,
    (r.realizationdate)::date AS realization_date,
    r.realizationdescription AS realization_description,
    r.realizationamount AS realization_amount,
    r.realizationtype AS realization_type,
    rm.realmemonumber AS memo_number,
    rm.realmemosubject AS memo_subject,
    rr.branchcode AS branch_code,
    rr.inputuser AS input_user,
    (rr.inputdate)::date AS input_date,
    rr.authuser AS auth_user,
    (rr.authdate)::date AS auth_date
   FROM ((program.realizationreturn rr
     JOIN program.realization r ON ((r.realizationid = rr.realizationid)))
     JOIN program.realizationmemo rm ON ((rm.realmemoid = r.realmemoid)));


--
-- Name: v_report_mustahiq_list; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_report_mustahiq_list AS
 SELECT m.mustahiqid AS mustahiq_id,
    m.mustahiqtype AS mustahiq_type,
    c.customername AS customer_name,
    c.addressstreet AS address_street,
    c.addresskelurahan AS address_kelurahan,
    c.addresskecamatan AS address_kecamatan,
    c.addresscity AS address_city,
    c.phonenumber AS phone_number,
    COALESCE(cc.cpname, ''::character varying) AS cp_name,
    COALESCE(cc.cpphonenumber, ''::character varying) AS cp_phone_number,
    COALESCE(cc.cpmobilenumber, ''::character varying) AS cp_mobile_number,
    COALESCE(ev.enum_description, ''::character varying) AS ashnaf_label,
    COALESCE(mp.productid, 0) AS product_id,
    COALESCE(pr.productname, ''::character varying) AS product_name,
    (mp.datestart)::date AS date_start,
    (COALESCE(mp.distributionamount, (0)::numeric))::double precision AS distribution_amount,
    COALESCE(mai.schoolname, ''::character varying) AS school_name,
    COALESCE(mai.sd_kelas, ''::character varying) AS sd_kelas,
    COALESCE((EXTRACT(year FROM mai.sd_tahunawal))::integer, 0) AS sd_tahun_awal,
    COALESCE((EXTRACT(year FROM mai.sd_tahunakhir))::integer, 0) AS sd_tahun_akhir,
    COALESCE(mai.smp_kelas, ''::character varying) AS smp_kelas,
    COALESCE((EXTRACT(year FROM mai.smp_tahunawal))::integer, 0) AS smp_tahun_awal,
    COALESCE((EXTRACT(year FROM mai.smp_tahunakhir))::integer, 0) AS smp_tahun_akhir,
    COALESCE(mai.sma_kelas, ''::character varying) AS sma_kelas,
    COALESCE((EXTRACT(year FROM mai.sma_tahunawal))::integer, 0) AS sma_tahun_awal,
    COALESCE((EXTRACT(year FROM mai.sma_tahunakhir))::integer, 0) AS sma_tahun_akhir,
    COALESCE(mai.universitas_kelas, ''::character varying) AS universitas_kelas,
    COALESCE((EXTRACT(year FROM mai.universitas_tahunawal))::integer, 0) AS universitas_tahun_awal,
    COALESCE((EXTRACT(year FROM mai.universitas_tahunakhir))::integer, 0) AS universitas_tahun_akhir,
    COALESCE(mai.achievement, ''::character varying) AS achievement,
    COALESCE(sc.customername, ''::character varying) AS supervisor_name
   FROM ((((((((program.mustahiq m
     JOIN program.customer c ON ((c.customerid = m.customerid)))
     LEFT JOIN program.customercorporate cc ON ((cc.customerid = m.customerid)))
     LEFT JOIN program.mustahiqproduct mp ON ((mp.mustahiqid = m.mustahiqid)))
     LEFT JOIN program.product pr ON ((pr.productid = mp.productid)))
     LEFT JOIN program.mustahiqadditionalinfo mai ON ((mai.mustahiqproductid = mp.mustahiqproductid)))
     LEFT JOIN transaction.enum_varchar ev ON ((((ev.enum_name)::text = 'eAshnaf'::text) AND (((ev.enum_value)::character varying)::text = ((m.ashnaf)::character varying)::text))))
     LEFT JOIN program.mustahiq sv ON ((sv.mustahiqid = mai.mustahiqidsupervisor)))
     LEFT JOIN program.customer sc ON ((sc.customerid = sv.customerid)));


--
-- Name: v_report_realization_by_mustahiq; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_report_realization_by_mustahiq AS
 SELECT c.customerid AS customer_id,
    c.customername AS customer_name,
    c.addressstreet AS address_street,
    pr.productid AS product_id,
    pr.productname AS product_name,
    pgr.productgroupname AS product_group_name,
    (r.realizationdate)::date AS realization_date,
    rd.realizationamount AS realization_amount,
    rd.detaildescription AS detail_description,
    COALESCE(fa.accountname, ''::character varying) AS account_name,
    COALESCE(po.proposalno, ''::character varying) AS proposal_no,
    COALESCE(po.proposalnominal, (0)::double precision) AS proposal_nominal,
    COALESCE(po.proposaldescription, ''::character varying) AS proposal_description,
    COALESCE(po.proposalreferenceby, ''::character varying) AS proposal_reference_by,
    COALESCE(bq.budget_code, ''::character varying) AS budget_code,
        CASE
            WHEN (bq.parent_item_name IS NOT NULL) THEN (concat(bq.item_name, ' - ', bq.parent_item_name))::character varying
            ELSE COALESCE(bq.item_name, ''::character varying)
        END AS budget_item_description,
    COALESCE(mp.branchcode, ''::character varying) AS branch_code,
    r.realizationid AS realization_id
   FROM (((((((((program.product pr
     JOIN program.productgroup pgr ON ((pgr.productgroupid = pr.productgroupid)))
     JOIN program.mustahiqproduct mp ON ((mp.productid = pr.productid)))
     JOIN program.realization r ON ((r.realizationid IN ( SELECT rd2.realizationid
           FROM program.realizationdetail rd2
          WHERE (rd2.mustahiqproductid = mp.mustahiqproductid)))))
     JOIN program.realizationdetail rd ON (((rd.realizationid = r.realizationid) AND (rd.mustahiqproductid = mp.mustahiqproductid))))
     JOIN program.mustahiq m ON ((m.mustahiqid = mp.mustahiqid)))
     JOIN program.customer c ON ((c.customerid = m.customerid)))
     LEFT JOIN program.proposal po ON ((po.proposalid = mp.proposalid)))
     LEFT JOIN transaction.financialaccount fa ON (((fa.accountno)::text = (mp.accountno)::text)))
     LEFT JOIN ( SELECT rb.realizationid,
            bdg.budgetcode AS budget_code,
            bdi.budgetitemname AS item_name,
            bdip.budgetitemname AS parent_item_name
           FROM (((program.realizationbudget rb
             JOIN transaction.budget bdg ON ((bdg.budgetid = rb.budgetid)))
             JOIN transaction.budgetitem bdi ON ((bdi.itemid = bdg.itemid)))
             LEFT JOIN transaction.budgetitem bdip ON ((bdip.itemid = bdi.parentitemid)))) bq ON ((bq.realizationid = r.realizationid)));


