        CASE
            WHEN (bq.parent_item_name IS NOT NULL) THEN (concat(bq.item_name, ' - ', bq.parent_item_name))::character varying
            ELSE COALESCE(bq.item_name, ''::character varying)
        END AS budget_item_description,
    COALESCE(mp.branchcode, ''::character varying) AS branch_code
   FROM ((((((((((program.product pr
     JOIN program.program g ON (((g.productid = pr.productid) AND (((g.programtype)::character varying)::text = 'N'::text))))
     JOIN program.productgroup pgr ON ((pgr.productgroupid = pr.productgroupid)))
     JOIN program.mustahiqproduct mp ON ((mp.productid = pr.productid)))
     JOIN program.realization r ON ((r.realizationid IN ( SELECT rd2.realizationid
           FROM program.realizationdetail rd2
          WHERE (rd2.mustahiqproductid = mp.mustahiqproductid)))))
     JOIN program.realizationdetail rd ON (((rd.realizationid = r.realizationid) AND (rd.mustahiqproductid = mp.mustahiqproductid))))
     JOIN program.mustahiq m ON ((m.mustahiqid = mp.mustahiqid)))
     JOIN program.customer c ON ((c.customerid = m.customerid)))
     LEFT JOIN program.proposal po ON ((po.proposalid = mp.proposalid)))
     LEFT JOIN transaction.financialaccount fa ON (((fa.accountno)::text = (mp.accountno)::text)))
     LEFT JOIN ( SELECT rb.realizationid,
            bdg.budgetcode AS budget_code,
            bdi.budgetitemname AS item_name,
            bdip.budgetitemname AS parent_item_name
           FROM (((program.realizationbudget rb
             JOIN transaction.budget bdg ON ((bdg.budgetid = rb.budgetid)))
             JOIN transaction.budgetitem bdi ON ((bdi.itemid = bdg.itemid)))
             LEFT JOIN transaction.budgetitem bdip ON ((bdip.itemid = bdi.parentitemid)))) bq ON ((bq.realizationid = r.realizationid)));


--
-- Name: v_report_realization_regular; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_report_realization_regular AS
 SELECT pr.productid AS product_id,
    pr.productname AS product_name,
    pgr.productgroupname AS product_group_name,
    mp.mustahiqproductname AS mustahiq_product_name,
    c.customername AS customer_name,
    c.addressstreet AS address_street,
    r.realizationid AS realization_id,
    (r.realizationdate)::date AS realization_date,
    r.statusreceivables AS status_receivables,
    rd.realizationamount AS realization_amount,
    (COALESCE(s.reportamount, (0)::numeric))::double precision AS report_amount,
    COALESCE(s.reportdetailstatus, '0'::character varying) AS report_detail_status,
    COALESCE(bq.budget_code, ''::character varying) AS budget_code,
        CASE
            WHEN (bq.parent_item_name IS NOT NULL) THEN (concat(bq.item_name, ' - ', bq.parent_item_name))::character varying
            ELSE COALESCE(bq.item_name, ''::character varying)
        END AS budget_item_description
   FROM (((((((((program.product pr
     JOIN program.program g ON (((g.productid = pr.productid) AND (((g.programtype)::character varying)::text = 'R'::text))))
     JOIN program.productgroup pgr ON ((pgr.productgroupid = pr.productgroupid)))
     JOIN program.mustahiqproduct mp ON ((mp.productid = pr.productid)))
     JOIN program.realization r ON ((r.realizationid IN ( SELECT rd2.realizationid
           FROM program.realizationdetail rd2
          WHERE (rd2.mustahiqproductid = mp.mustahiqproductid)))))
     JOIN program.realizationdetail rd ON (((rd.realizationid = r.realizationid) AND (rd.mustahiqproductid = mp.mustahiqproductid))))
     JOIN program.mustahiq m ON ((m.mustahiqid = mp.mustahiqid)))
     JOIN program.customer c ON ((c.customerid = m.customerid)))
     LEFT JOIN program.statusrecrepdetail s ON ((s.realizationdetailid = rd.realizationdetailid)))
     LEFT JOIN ( SELECT rb.realizationid,
            bdg.budgetcode AS budget_code,
            bdi.budgetitemname AS item_name,
            bdip.budgetitemname AS parent_item_name
           FROM (((program.realizationbudget rb
             JOIN transaction.budget bdg ON ((bdg.budgetid = rb.budgetid)))
             JOIN transaction.budgetitem bdi ON ((bdi.itemid = bdg.itemid)))
             LEFT JOIN transaction.budgetitem bdip ON ((bdip.itemid = bdi.parentitemid)))) bq ON ((bq.realizationid = r.realizationid)));


--
-- Name: v_report_realization_return; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_report_realization_return AS
 SELECT rr.returnid AS return_id,
    (rr.returndate)::date AS return_date,
    (r.realizationamount)::double precision AS realization_amount,
    (rr.returnamount)::double precision AS return_amount,
    rm.realmemonumber AS memo_number,
    rr.returndescription AS return_description,
    rr.inputuser AS input_user,
    r.realizationid AS realization_id,
    COALESCE(ci.costitemdescription, ''::character varying) AS cost_item_description,
    (COALESCE(rc.costamount, (0)::numeric))::double precision AS cost_amount
   FROM ((((program.realizationreturn rr
     JOIN program.realization r ON ((r.realizationid = rr.realizationid)))
     JOIN program.realizationmemo rm ON ((rm.realmemoid = r.realmemoid)))
     LEFT JOIN program.realizationcost rc ON ((rc.returnid = rr.returnid)))
     LEFT JOIN program.costitem ci ON ((ci.costitemid = rc.costitemid)));


--
-- Name: v_upz_trx; Type: VIEW; Schema: dwh; Owner: -
--

CREATE VIEW dwh.v_upz_trx AS
 SELECT a.account_code,
    a.account_name,
    j.journal_no,
    j.journal_date,
    ji.branch_code,
    t.transactionno,
    t.transactioncode,
    ty.description AS trxtypedesc,
    ji.additionaldescription,
    ji.description,
    ji.subaccountcode,
    ji.subaccountname,
    (ji.amount_debit)::double precision AS amount_debit,
    (ji.amount_credit)::double precision AS amount_credit,
    (EXISTS ( SELECT 1
           FROM transaction.journalitem r
          WHERE (((r.fl_journal)::text = (j.journal_no)::text) AND ((r.fl_account)::text = '210302'::text)))) AS has_210302,
    (EXISTS ( SELECT 1
           FROM transaction.journalitem r
          WHERE (((r.fl_journal)::text = (j.journal_no)::text) AND ((r.fl_account)::text = '110109'::text)))) AS has_110109
   FROM ((((transaction.journalitem ji
     JOIN transaction.journal j ON (((j.journal_no)::text = (ji.fl_journal)::text)))
     JOIN transaction.account a ON (((a.account_code)::text = (ji.fl_account)::text)))
     LEFT JOIN transaction.transaction t ON (((t.journalno)::text = (j.journal_no)::text)))
     LEFT JOIN transaction.transactiontype ty ON (((ty.transactioncode)::text = (t.transactioncode)::text)));


